    BLIZZARD = { name = "Blizzard", ziel = { "Der Winter kennt keine Gnade!", "*wirkt Blizzard auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Der Winter kennt keine Gnade!", "*konzentriert sich und entfesselt Blizzard.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Ruhe. Selbst die Luft hält jetzt den Atem an.", "*zieht einen Reif aus Eiskristallen durch die Luft.*", "Kälte belohnt jene, die Geduld haben.", "*lässt eine Schneeflocke auf der Hand wachsen.*", "Der Wetterbericht hat sich soeben verschlechtert.", "*ruft ein Wirbeln aus Schnee und scharfkantigem Eis herbei.*" } },
    FROST_NOVA = { name = "Frostnova", ziel = { "Keinen Schritt weiter, %s!", "*wirkt Frostnova auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Keinen Schritt weiter!", "*konzentriert sich und entfesselt Frostnova.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Ruhe. Selbst die Luft hält jetzt den Atem an.", "*zieht einen Reif aus Eiskristallen durch die Luft.*", "Kälte belohnt jene, die Geduld haben.", "*lässt eine Schneeflocke auf der Hand wachsen.*", "Ihr bleibt genau hier. Die Kälte besteht darauf.", "*lässt eisige Ranken über den Boden kriechen.*" } },
    CONE_OF_COLD = { name = "Kältekegel", ziel = { "Ein Hauch des Nordens!", "*wirkt Kältekegel auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Ein Hauch des Nordens!", "*konzentriert sich und entfesselt Kältekegel.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Ruhe. Selbst die Luft hält jetzt den Atem an.", "*zieht einen Reif aus Eiskristallen durch die Luft.*", "Kälte belohnt jene, die Geduld haben.", "*lässt eine Schneeflocke auf der Hand wachsen.*" } },
    ICE_BARRIER = { name = "Eisbarriere", ziel = {  }, gruppe = { "Kälte ist mein Schild.", "*konzentriert sich und entfesselt Eisbarriere.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*" } },
    ICE_BLOCK = { name = "Eisblock", ziel = {  }, gruppe = { "Ich bin kurz nicht zu sprechen.", "*konzentriert sich und entfesselt Eisblock.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Vorsicht ist eine Kunst, keine Schwäche.", "*zieht einen leuchtenden Kreis um die Schultern.*", "Besser geschützt als überrascht.", "*prüft die Kanten eines schimmernden Schutzzaubers.*", "Bitte nicht stören. Ich bin gerade tiefgekühlt.", "*schließt sich in kristallklarem Eis ein.*" } },
    ARCANE_EXPLOSION = { name = "Arkane Explosion", ziel = { "Abstand halten, die Magie wird unruhig!", "*wirkt Arkane Explosion auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Abstand halten, die Magie wird unruhig!", "*konzentriert sich und entfesselt Arkane Explosion.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*" } },
    COUNTERSPELL = { name = "Gegenzauber", ziel = { "Eure Worte enden hier, %s!", "*wirkt Gegenzauber auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Eure Worte enden hier!", "*konzentriert sich und entfesselt Gegenzauber.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Ein schöner Zauber. Schade um die letzte Silbe.", "*zerreißt die fremde Formel mit einer knappen Handbewegung.*" } },
    POLYMORPH = { name = "Verwandlung", ziel = { "Ein wenig Wolle steht Euch gut, %s.", "*wirkt Verwandlung auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Ein wenig Wolle steht Euch gut.", "*konzentriert sich und entfesselt Verwandlung.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Ein wenig Wolle würde Euch gut stehen.", "*überlegt kurz, ob Hörner besser wären.*", "Keine Sorge. Das ist meistens reversibel.", "*skizziert die Umrisse eines Schafes.*", "Ich verspreche, die Verwandlung steht Euch ausgezeichnet.", "*mustert sein Gegenüber wie ein Schneider mit sehr viel Fantasie.*" } },
    BLINK = { name = "Blinzeln", ziel = {  }, gruppe = { "Einen Augenblick, ich bin gleich woanders.", "*konzentriert sich und entfesselt Blinzeln.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Der kürzeste Weg ist gelegentlich sehr indirekt.", "*faltet eine Landkarte zu einem glühenden Punkt.*", "Falls ich verschwinde, waren es die Koordinaten.", "*prüft die Sterne und schließt die Augen.*", "Ihr schaut in die falsche Richtung.", "*verschwindet in einem kurzen Flimmern der Luft.*" } },
    SLOW_FALL = { name = "Langsamer Fall", ziel = { "Die Schwerkraft kann heute warten.", "*wirkt Langsamer Fall auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Die Schwerkraft kann heute warten.", "*konzentriert sich und entfesselt Langsamer Fall.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Der kürzeste Weg ist gelegentlich sehr indirekt.", "*faltet eine Landkarte zu einem glühenden Punkt.*", "Falls ich verschwinde, waren es die Koordinaten.", "*prüft die Sterne und schließt die Augen.*" } },
    EVOCATION = { name = "Hervorrufung", ziel = {  }, gruppe = { "Einen Moment, ich sammle meine Gedanken und mein Mana.", "*konzentriert sich und entfesselt Hervorrufung.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Die Gleichung ist elegant. Die Folgen weniger.", "*ordnet schwebende Glyphen in einer exakten Reihe.*", "Magie ist Mathematik mit schlechterer Fehlerbehandlung.", "*spannt einen Faden aus violettem Licht.*", "Geduld. Meine Reserven sind nicht unerschöpflich.", "*zieht langsam arkane Ströme aus der Umgebung.*" } },
    ARCANE_INTELLECT = { name = "Arkane Intelligenz", ziel = { "Ein klarer Geist ist die beste Waffe, %s.", "*wirkt Arkane Intelligenz auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Ein klarer Geist ist die beste Waffe.", "*konzentriert sich und entfesselt Arkane Intelligenz.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Ein klarer Geist wirkt Wunder, ganz ohne Wunder.", "*legt zwei Finger an die Stirn.*", "Wissen ist der angenehmste aller Vorteile.", "*überträgt eine sanft leuchtende Glyphe.*", "Ein geschärfter Verstand wiegt mehr als ein ganzer Waffenschrank.", "*setzt eine leuchtende Rune behutsam auf die Stirn.*" } },
    ARCANE_BRILLIANCE = { name = "Arkane Brillanz", ziel = { "Mögen unsere Gedanken heller leuchten!", "*wirkt Arkane Brillanz auf %s.*", "%s, Ihr werdet noch von dieser Formel hören!", "*richtet eine sorgfältig gezogene Rune auf %s.*" }, gruppe = { "Mögen unsere Gedanken heller leuchten!", "*konzentriert sich und entfesselt Arkane Brillanz.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Ein klarer Geist wirkt Wunder, ganz ohne Wunder.", "*legt zwei Finger an die Stirn.*", "Wissen ist der angenehmste aller Vorteile.", "*überträgt eine sanft leuchtende Glyphe.*" } },
