    CONJURE_FOOD = { name = "Essen herbeizaubern", ziel = {  }, gruppe = { "Ein bisschen Magie gegen den Hunger.", "*konzentriert sich und entfesselt Essen herbeizaubern.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Etwas Essbares ist auch eine Form hoher Magie.", "*schüttelt ein paar Funken aus dem Ärmel.*", "Hoffentlich ist die Rezeptur diesmal nicht zu süß.", "*prüft das frisch herbeigezauberte Ergebnis.*", "Ein bisschen Brot hat schon manch heldenhafte Reise gerettet.", "*zaubert mit einer Verbeugung einen kleinen Imbiss hervor.*" } },
    CONJURE_WATER = { name = "Wasser herbeizaubern", ziel = {  }, gruppe = { "Frisches Wasser aus reiner Magie.", "*konzentriert sich und entfesselt Wasser herbeizaubern.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Etwas Essbares ist auch eine Form hoher Magie.", "*schüttelt ein paar Funken aus dem Ärmel.*", "Hoffentlich ist die Rezeptur diesmal nicht zu süß.", "*prüft das frisch herbeigezauberte Ergebnis.*", "Wasser ist die vernünftigste aller Beschwörungen.", "*lässt perlende Tropfen zu einer Karaffe verschmelzen.*" } },
    CREATE_MANA_GEM = { name = "Manastein erschaffen", ziel = {  }, gruppe = { "Ein kleiner Vorrat für große Not.", "*konzentriert sich und entfesselt Manastein erschaffen.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Etwas Essbares ist auch eine Form hoher Magie.", "*schüttelt ein paar Funken aus dem Ärmel.*", "Hoffentlich ist die Rezeptur diesmal nicht zu süß.", "*prüft das frisch herbeigezauberte Ergebnis.*" } },
    PORTAL = { name = "Portal", ziel = {  }, gruppe = { "Bitte beim Durchgang keine Gliedmaßen verlieren.", "*konzentriert sich und entfesselt Portal.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Bitte die Gliedmaßen innerhalb des Portals behalten.", "*prüft zweimal die Zielkoordinaten.*", "Reisekosten: etwas Mana und volles Vertrauen.", "*öffnet einen schimmernden Durchgang.*", "Wer zuerst hindurchgeht, darf mir anschließend berichten.", "*prüft misstrauisch die Farbe des Portalrandes.*" } },
    TELEPORT = { name = "Teleportieren", ziel = {  }, gruppe = { "Ich nehme die Abkürzung durch das Raumgefüge.", "*konzentriert sich und entfesselt Teleportieren.*", "Die arkane Theorie sieht das jedenfalls so vor.", "*zieht mit zwei Fingern eine flüchtige Rune in die Luft.*", "Der letzte Versuch war weniger elegant.", "*murmelt eine Formel und verfolgt aufmerksam die aufsteigenden Funken.*", "Der kürzeste Weg ist gelegentlich sehr indirekt.", "*faltet eine Landkarte zu einem glühenden Punkt.*", "Falls ich verschwinde, waren es die Koordinaten.", "*prüft die Sterne und schließt die Augen.*" } },
